<template>
  <section v-if="instance" class="surface" v-loading="loading"><div class="toolbar"><div><h2>密钥别名</h2><p>密钥明文只能写入，永远不会回传。</p></div><el-button v-if="canManage" type="primary" @click="openCreate">写入密钥</el-button></div><el-table :data="secrets"><el-table-column prop="alias" label="别名" min-width="200"><template #default="{row}"><code>{{row.alias}}</code></template></el-table-column><el-table-column prop="keyVersion" label="版本" width="90"/><el-table-column label="最后使用" min-width="170"><template #default="{row}">{{row.lastUsedAt?new Date(row.lastUsedAt).toLocaleString():'从未使用'}}</template></el-table-column><el-table-column v-if="canManage" label="操作" width="150"><template #default="{row}"><el-button link @click="rotate(row.alias)">轮换</el-button><el-button link type="danger" @click="remove(row.alias)">删除</el-button></template></el-table-column></el-table><el-empty v-if="!secrets.length&&!loading" description="暂无密钥别名"/>
    <el-dialog v-model="dialog" :title="rotating?'轮换密钥':'写入密钥'" width="500px"><el-form label-position="top"><el-form-item label="别名"><el-input v-model="form.alias" :disabled="rotating"/></el-form-item><el-form-item label="密钥值"><el-input v-model="form.value" type="password" show-password/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog>
  </section>
</template>
<script setup lang="ts">
import {ref,watch} from 'vue';import {ElMessage,ElMessageBox} from 'element-plus';import type {DeveloperProductInstanceDto,DeveloperSecretDto} from '@/client/types.gen';import {developerProductService} from '@/service/developerProductService';const props=defineProps<{instance?:DeveloperProductInstanceDto;canManage:boolean}>();const loading=ref(false),secrets=ref<DeveloperSecretDto[]>([]),dialog=ref(false),rotating=ref(false),form=ref({alias:'',value:''});const load=async()=>{if(!props.instance)return;loading.value=true;try{secrets.value=await developerProductService.listSecretResources(props.instance.id)}finally{loading.value=false}};const openCreate=()=>{rotating.value=false;form.value={alias:'',value:''};dialog.value=true};const rotate=(alias:string)=>{rotating.value=true;form.value={alias,value:''};dialog.value=true};const save=async()=>{if(!props.instance)return;await developerProductService.upsertSecretResource(props.instance.id,form.value);dialog.value=false;await load();ElMessage.success(rotating.value?'密钥已轮换':'密钥已写入')};const remove=async(alias:string)=>{if(!props.instance)return;await ElMessageBox.confirm(`删除密钥别名 ${alias} 后无法恢复。`,'删除密钥',{type:'warning'});await developerProductService.deleteSecretResource(props.instance.id,alias);await load();ElMessage.success('密钥已删除')};watch(()=>props.instance?.id,load,{immediate:true})
</script><style scoped>.toolbar{display:flex;justify-content:space-between;gap:16px;align-items:flex-start;margin-bottom:16px}.toolbar h2{margin:0 0 6px;font-size:17px}.toolbar p{margin:0;color:var(--el-text-color-secondary)}</style>
